/* ===================== BÀI 21 · Cấu trúc cổng và Port 0 ===================== */
/* Bài 21 · Cấu trúc cổng và Port 0 (AMTS-EMB-001-M06-L01, MC51-021) — sinh bởi tools/author/mcu8051/l21.py, không sửa tay.
   Ví dụ cho trình mô phỏng 8051 và bài tập chấm tự động (đề, code mẫu, bộ thử). Lời giải không nằm ở đây. */
const PR21=[{"label":"Ví dụ: Đọc chân P3, LED đi theo nút K1","code":"; Ví dụ 1: đọc mức chân P3, LED P1.0 đi theo nút K1\n; Chip: AT89S52. Bấm giữ K1 (P3.2) rồi bấm Từng bước.\n        ORG     0000H\n        MOV     A,P3                    ; đọc mức 8 CHÂN của P3\n        MOV     30H,A                   ; cất lại để xem trong Bộ nhớ\n        MOV     C,P3.2                  ; đọc riêng chân K1: 0 = đang bấm\n        MOV     P1.0,C                  ; LED P1.0 sáng khi chân = 0\n        SJMP    $\n        END\n","note":"Bấm Từng bước 4 lần khi không bấm nút: A = FFH, P1.0 giữ 1. Chạy lại và giữ K1 (P3.2) trước khi bước: A = FBH, LED P1.0 sáng. Đoán trước: giữ K2 (P3.3) thì 30H bằng bao nhiêu? (F7H, LED không sáng vì P1.0 đi theo K1.)","dev":{"led":true,"btn":true},"fosc":12000000},{"label":"Ví dụ: Ghi 1 vào chốt trước khi đọc chân","code":"; Ví dụ 2: muốn đọc chân làm ngõ vào, chốt phải bằng 1\n; P1.0 và P1.2 nối công tắc xuống GND (giả định).\n        ORG     0000H\n        MOV     P1,#0F0H                ; nửa thấp đang xuất 0\n        MOV     A,P1                    ; đọc chân: nửa thấp luôn là 0\n        MOV     R2,A                    ; R2 không thấy công tắc nào\n        ORL     P1,#0FH                 ; ghi 1 vào chốt nửa thấp\n        MOV     A,P1                    ; giờ chân đi theo công tắc\n        MOV     R3,A\n        SJMP    $\n        END\n","note":"Công tắc ở P1.0 và P1.2 đóng suốt thời gian chạy. Lệnh 2 đọc chân khi chốt nửa thấp = 0: R2 = F0H, không thấy công tắc. Sau ORL P1,#0FH (chốt = FFH), lệnh 5 đọc R3 = FAH: bit 0 và bit 2 = 0 đúng là hai công tắc.","dev":{"led":true,"pull":{"P1":"FA"}},"fosc":12000000},{"label":"Bẫy: P0 không có điện trở kéo lên","code":"; Bẫy 3: P0 làm ngõ vào nhưng không có điện trở kéo lên\n; Chạy với P0 KHÔNG có điện trở kéo lên ngoài.\n        ORG     0000H\n        MOV     A,P0                    ; chốt P0 = FFH sau reset\n        MOV     30H,A                   ; chân thả nổi: mức không xác định\n        MOV     P1,A                    ; LED: tưởng mọi nút đều bấm\n        SJMP    $\n        END\n","note":"P0 không có điện trở kéo lên: chốt FFH làm transistor tắt, chân thả nổi. Trình mô phỏng đọc 0 và cảnh báo; 8 LED sáng như thể 8 nút cùng bấm. Trên chip thật mức đọc không xác định. Có kéo lên ngoài thì A = FFH.","dev":{"led":true,"p0float":true},"fosc":12000000},{"label":"Ví dụ: Đọc chốt và đọc chân khác nhau","code":"; Ví dụ 4: đọc-sửa-ghi đọc CHỐT, MOV A,P1 đọc CHÂN\n; P1.0 nối thẳng cực B transistor: chân bị ghìm ở 0.\n        ORG     0000H\n        MOV     A,P1                    ; đọc chân: bit 0 = 0 dù chốt = 1\n        MOV     30H,A\n        CPL     P1.7                    ; đọc-sửa-ghi: đọc CHỐT, đảo bit 7\n        MOV     A,P1                    ; đọc chân lần nữa\n        MOV     31H,A\n        SJMP    $\n        END\n","note":"Tải ghìm P1.0 ở 0 trong khi chốt = 1. Lệnh 1 đọc chân: 30H = FEH. CPL P1.7 đọc CHỐT (FFH) nên chốt thành 7FH, bit 0 vẫn 1. Lệnh 4 đọc chân: 31H = 7EH. Đoán trước: sau CPL P1.7, chốt P1 bằng bao nhiêu?","dev":{"led":true,"pull":{"P1":"FE"}},"fosc":12000000},{"label":"Lỗi: Đọc chân rồi ghi lại cả cổng","code":"; Lỗi 5: đọc chân rồi ghi lại cả cổng để đảo P1.7\n; Cùng mạch với ví dụ 4: chân P1.0 bị tải ghìm ở 0.\n        ORG     0000H\n        MOV     A,P1                    ; đọc CHÂN: FEH chứ không phải FFH\n        XRL     A,#80H                  ; đảo bit 7\n        MOV     P1,A                    ; ghi cả byte: chốt P1.0 thành 0!\n        SJMP    $\n        END\n","note":"Cùng mạch với ví dụ 4. MOV A,P1 đọc chân FEH, đảo bit 7 thành 7EH rồi ghi cả byte: chốt P1.0 bị xóa về 0 — tải ở P1.0 bị tắt (hoặc bật) ngoài ý muốn. So chốt cuối 7EH với 7FH của ví dụ 4.","dev":{"led":true,"pull":{"P1":"FE"}},"fosc":12000000}];
const sim21=makeSim51(document.getElementById("m51-l21"),{id:"s21",presets:PR21,ram:256});
makeEx51(document.getElementById("ex-l21"),"l21",[{"t":"Bốn nút thành một byte cờ","d":"<p>Bốn nút K1–K4 nối các chân <code>P3.2<\/code>–<code>P3.5<\/code> xuống GND: bấm thì chân = 0. Viết chương trình đọc P3 một lần và ghi vào ô <code>30H<\/code> một byte cờ: bit <i>k<\/i> (k = 0…3) bằng 1 khi nút K(<i>k<\/i>+1) <b>đang bấm<\/b>; bit 4–7 bằng 0. Các chân P3 khác (P3.0, P3.1, P3.6, P3.7) có thể đang ở 0 và phải bị bỏ qua. Chốt P3 phải giữ <code>FFH<\/code>. Kết thúc bằng <code>SJMP $<\/code>.<\/p><p>Ví dụ: chỉ K1 bấm → chân P3 = <code>FBH<\/code> → <code>30H = 01H<\/code>.<\/p>","start":"        ORG     0000H\n        MOV     A,P3                    ; đọc 8 chân P3\n        RR      A\n        RR      A                       ; K1..K4 về bit 0..3\n        ANL     A,#0FH                  ; bỏ các chân khác\n        MOV     30H,A\n        SJMP    $\n        END\n","spec":{"cases":[{"setup":{"pins":{"P3":251}},"expect":{"iram":{"0x30":1},"ports":{"P3":255}}},{"setup":{"pins":{"P3":255}},"expect":{"iram":{"0x30":0},"ports":{"P3":255}}},{"setup":{"pins":{"P3":195}},"expect":{"iram":{"0x30":15},"ports":{"P3":255}}},{"setup":{"pins":{"P3":231}},"expect":{"iram":{"0x30":6},"ports":{"P3":255}}},{"setup":{"pins":{"P3":59}},"expect":{"iram":{"0x30":1},"ports":{"P3":255}}},{"setup":{"pins":{"P3":223}},"expect":{"iram":{"0x30":8},"ports":{"P3":255}}}]},"hints":["Đọc cả cổng bằng MOV A,P3 (đọc chân). Không ghi gì vào P3 để chốt giữ FFH.","Bấm = 0 nhưng cờ cần bấm = 1: đảo cả 8 bit của A bằng một lệnh 1 byte, 1 chu kỳ.","Sau khi đảo, K1 vẫn ở bit 2: cần dời nó về bit 0 rồi xóa các bit không dùng."],"why":"Chân nút tích cực mức thấp nên phải đảo cả byte; nút nằm ở P3.2–P3.5 nên dịch về bit 0–3 rồi che các bit còn lại. Bộ thử 5 có P3.0, P3.1, P3.6, P3.7 = 0 để bắt chương trình quên che."},{"t":"Lưu mức chân, đảo P1.7 đúng cách","d":"<p>Trên cổng P1 có tải có thể ghìm một số chân ở mức 0 trong khi chốt vẫn bằng 1 (giả định: cực B transistor nối thẳng vào chân). Viết chương trình: (1) lưu <b>mức chân<\/b> P1 lúc bắt đầu vào ô <code>31H<\/code>; (2) đảo trạng thái đèn báo ở P1.7, tức đảo <b>bit 7 của chốt<\/b> (sau reset là 1 → thành 0); (3) mọi bit chốt khác của P1 giữ nguyên <code>1<\/code>. Kết thúc bằng <code>SJMP $<\/code>.<\/p><p>Ví dụ: tải ghìm P1.0 → chân P1 = <code>FEH<\/code> → <code>31H = FEH<\/code>, chốt <code>P1 = 7FH<\/code>.<\/p>","start":"        ORG     0000H\n        MOV     A,P1                    ; mức chân P1\n        MOV     31H,A                   ; lưu mức chân\n        XRL     A,#80H                  ; đảo bit 7\n        MOV     P1,A                    ; ghi lại cả cổng\n        SJMP    $\n        END\n","spec":{"cases":[{"setup":{"pins":{"P1":254}},"expect":{"iram":{"0x31":254},"ports":{"P1":127}}},{"setup":{"pins":{"P1":255}},"expect":{"iram":{"0x31":255},"ports":{"P1":127}}},{"setup":{"pins":{"P1":126}},"expect":{"iram":{"0x31":126},"ports":{"P1":127}}},{"setup":{"pins":{"P1":0}},"expect":{"iram":{"0x31":0},"ports":{"P1":127}}},{"setup":{"pins":{"P1":170}},"expect":{"iram":{"0x31":170},"ports":{"P1":127}}},{"setup":{"pins":{"P1":127}},"expect":{"iram":{"0x31":127},"ports":{"P1":127}}}]},"hints":["Lệnh MOV địa chỉ trực tiếp → địa chỉ trực tiếp (3 byte) chép mức chân P1 thẳng vào ô 31H, không cần qua A; MOV đọc chân.","Code mẫu đọc chân vào A rồi ghi lại cả byte: bit 0 bị tải ghìm sẽ thành 0 trong chốt.","Lệnh bit trên cổng là lệnh đọc–sửa–ghi: nó đọc CHỐT, không đọc chân."],"why":"MOV A,P1 đọc chân; ghi A trở lại P1 sẽ chép mức 0 của chân bị tải ghìm vào chốt và tắt tải đó. CPL P1.7 là lệnh đọc–sửa–ghi: CPU đọc chốt (FFH), không đọc chân, nên các bit khác giữ nguyên. Bộ thử “không có tải” không phân biệt được hai cách; các bộ thử còn lại thì có."},{"t":"Ghép nút vào nửa thấp, ≤ 10 chu kỳ","d":"<p>Ô <code>30H<\/code> chứa một byte trạng thái. Xuất ra chốt <code>P1<\/code> một byte: nửa cao (bit 4–7) lấy từ nửa cao của <code>30H<\/code>; bit <i>k<\/i> của nửa thấp (k = 0…3) bằng <b>mức chân<\/b> <code>P3.(k+2)<\/code> (K1–K4, không đảo). <code>30H<\/code> giữ nguyên. Các chân P3.0, P3.1, P3.6, P3.7 không được lọt vào kết quả. Yêu cầu: toàn chương trình không quá <b>10 chu kỳ máy<\/b> (tính cả một lần <code>SJMP $<\/code>) và không quá <b>15 byte<\/b>.<\/p><p>Ví dụ: <code>30H = A5H<\/code>, không nút nào bấm (P3 = FFH) → <code>P1 = AFH<\/code>. Code mẫu cho kết quả đúng nhưng tốn 11 chu kỳ và 16 byte.<\/p>","start":"        ORG     0000H\n        MOV     A,P3                    ; mức chân P3\n        RR      A\n        RR      A                       ; K1..K4 về bit 0..3\n        ANL     A,#0FH\n        MOV     R2,A                    ; cất nửa thấp\n        MOV     A,30H\n        ANL     A,#0F0H                 ; nửa cao của 30H\n        ORL     A,R2                    ; ghép hai nửa\n        MOV     P1,A\n        SJMP    $\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x30":165},"pins":{"P3":255}},"expect":{"iram":{"0x30":165},"ports":{"P1":175}}},{"setup":{"iram":{"0x30":90},"pins":{"P3":251}},"expect":{"iram":{"0x30":90},"ports":{"P1":94}}},{"setup":{"iram":{"0x30":255},"pins":{"P3":195}},"expect":{"iram":{"0x30":255},"ports":{"P1":240}}},{"setup":{"iram":{"0x30":0},"pins":{"P3":255}},"expect":{"iram":{"0x30":0},"ports":{"P1":15}}},{"setup":{"iram":{"0x30":15},"pins":{"P3":231}},"expect":{"iram":{"0x30":15},"ports":{"P1":9}}},{"setup":{"iram":{"0x30":240},"pins":{"P3":59}},"expect":{"iram":{"0x30":240},"ports":{"P1":254}}}],"maxCyc":10,"maxBytes":15},"hints":["Code mẫu: 9 lệnh 1 chu kỳ + 2 chu kỳ SJMP $ = 11. Cần bỏ bớt một lệnh và thanh ghi trung gian R2.","Ghép bit theo mặt nạ không cần OR: kết quả = ((x XOR v) AND 0FH) XOR v lấy nửa thấp của x, nửa cao của v.","Áp công thức XOR–AND–XOR của gợi ý 2 với v là ô 30H; không cần thanh ghi trung gian."],"why":"Phép “trộn theo mặt nạ” r = ((x ⊕ v) ∧ m) ⊕ v cho bit của x ở chỗ mặt nạ m = 1 và bit của v ở chỗ m = 0, nên không cần cất nửa thấp vào R2 rồi OR. Lời giải: 7 lệnh × 1 chu kỳ + 2 chu kỳ SJMP $ = 9 chu kỳ, 14 byte."}]);

makeQuiz("quiz21","score21",[{"q": "Chốt P1 = FFH, mạch ngoài kéo chân P1.0 xuống 0. Sau lệnh CPL P1.7, chốt P1 bằng bao nhiêu?", "o": ["7FH", "7EH", "FEH", "80H"], "a": 0, "e": "CPL bit là lệnh đọc–sửa–ghi: CPU đọc CHỐT (FFH) chứ không đọc chân (FEH), đảo bit 7 rồi ghi lại byte → 7FH. 7EH là kết quả của cách làm sai MOV A,P1 / XRL A,#80H / MOV P1,A."}, {"q": "Chương trình vừa ghi MOV P1,#00H để bật 8 LED. Sau đó đọc MOV A,P1 để xem công tắc trên P1. A bằng bao nhiêu?", "o": ["FFH, bất kể công tắc", "Mức của các công tắc", "00H, bất kể công tắc", "Giá trị không xác định"], "a": 2, "e": "Chốt = 0 làm transistor kéo xuống dẫn, mọi chân bị giữ ở 0, nên đọc chân luôn ra 00H. Muốn đọc công tắc phải ghi 1 vào chốt các bit đó trước."}, {"q": "Vì sao đọc P0 làm ngõ vào trên bo không có điện trở kéo lên ngoài là sai thiết kế?", "o": ["P0 chỉ xuất được, không có đường đọc chân", "Chân P0 có chốt = 1 bị thả nổi, mức đọc không xác định", "P0 luôn đọc ra FFH", "Đọc P0 làm hỏng chốt P0"], "a": 1, "e": "P0 là cực máng hở khi làm cổng vào/ra: chốt = 1 thì không có gì kéo chân lên, chân thả nổi. P0 vẫn có đường đọc chân; vấn đề là mức trên chân không được xác định nếu thiếu điện trở kéo lên."}, {"q": "Lệnh nào sau đây đọc mức CHÂN của cổng (không phải chốt)?", "o": ["MOV C,P3.2", "SETB P1.1", "ORL P1,#0FH", "DJNZ P1,LAP"], "a": 0, "e": "MOV C,P3.2 lấy cổng làm nguồn nên đọc chân. SETB, ORL với đích là cổng và DJNZ trên cổng là lệnh đọc–sửa–ghi, đọc chốt."}, {"q": "Muốn đổi riêng bit P1.0 nhanh nhất mà không đụng bit khác, nên dùng lệnh nào?", "o": ["XRL P1,#01H (3 byte, 2 chu kỳ)", "MOV A,P1 / XRL A,#01H / MOV P1,A", "MOV P1,#0FEH", "CPL P1.0 (2 byte, 1 chu kỳ)"], "a": 3, "e": "CPL bit vừa là đọc–sửa–ghi vừa ngắn nhất. XRL P1,#01H cũng đúng nhưng tốn thêm 1 byte và 1 chu kỳ; cách ba lệnh đọc chân nên có thể làm hỏng bit khác; MOV P1,#0FEH ghi đè cả cổng."}]);

